[InitializeOnLoad]
public static class AirportRuinUpgrade
{
 const string Dir="Assets/Materials/FinalRanking/";
 static AirportRuinUpgrade(){EditorApplication.update+=Poll;}
 static void Poll(){if(!System.IO.File.Exists("Library/AirportRuin.request")||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;System.IO.File.Delete("Library/AirportRuin.request");try{Build();System.IO.File.WriteAllText("Library/AirportRuin.result","PASS: fractured aircraft, weathered airport, local cloud/dust atmosphere and right-aligned score columns saved.");}catch(Exception e){Debug.LogException(e);System.IO.File.WriteAllText("Library/AirportRuin.result","FAIL: "+e);}}
 static Material Mat(string n,Color c){string path=Dir+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.SetFloat("_Glossiness",.18f);return m;}
 static Transform Group(string n,Transform p,Vector3 pos){var t=new GameObject(n).transform;t.SetParent(p,false);t.localPosition=pos;return t;}
 static void Delete(string n){var g=GameObject.Find(n);if(g!=null)Object.DestroyImmediate(g);}
 static GameObject Box(string n,Transform p,Vector3 position,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=position;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<MeshFilter>().sharedMesh=BeveledBox();return g;}
 static void Beam(string n,Transform p,Vector3 a,Vector3 b,float width,Material m){var g=Box(n,p,(a+b)*.5f,new Vector3(width,(b-a).magnitude,width),m);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static Mesh BeveledBox(){string path="Assets/Prefabs/FinalRanking/Soft edged airport block.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh!=null)return mesh;var v=new List<Vector3>();var normals=new List<Vector3>();var triangles=new List<int>();var axes=new[]{Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};const int n=6;foreach(var normal in axes){Vector3 u=Mathf.Abs(normal.y)>.5f?Vector3.right:Vector3.up;Vector3 w=Vector3.Cross(normal,u);int start=v.Count;for(int y=0;y<=n;y++)for(int x=0;x<=n;x++){Vector3 p=normal*.5f+u*(x/(float)n-.5f)+w*(y/(float)n-.5f);Vector3 inner=new Vector3(Mathf.Clamp(p.x,-.445f,.445f),Mathf.Clamp(p.y,-.445f,.445f),Mathf.Clamp(p.z,-.445f,.445f));Vector3 direction=(p-inner).normalized;v.Add(inner+direction*.055f);normals.Add(direction);}for(int y=0;y<n;y++)for(int x=0;x<n;x++){int a=start+y*(n+1)+x;triangles.AddRange(new[]{a,a+1,a+n+2,a,a+n+2,a+n+1});}}mesh=new Mesh{name="Beveled cladding and luggage"};mesh.SetVertices(v);mesh.SetNormals(normals);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static Texture2D NoiseTexture(string n,Color dark,Color light,int size=512,bool ground=false){string path=Dir+n+".asset";var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(t==null){t=new Texture2D(size,size,TextureFormat.RGBA32,true){name=n,wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Trilinear};AssetDatabase.CreateAsset(t,path);}var pixels=new Color[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++){float a=Mathf.PerlinNoise(x*.018f,y*.018f)*.5f+Mathf.PerlinNoise(x*.09f+18,y*.09f)*.3f+Mathf.PerlinNoise(x*.55f,y*.55f)*.2f;float stain=Mathf.PerlinNoise(x*.008f+70,y*.008f+23);a=Mathf.Clamp01(a-(stain>.57f?(stain-.57f)*2:0));pixels[y*size+x]=Color.Lerp(dark,light,a);}t.SetPixels(pixels);t.Apply();EditorUtility.SetDirty(t);return t;}
 static Texture2D CloudTexture(){string path=Dir+"Layered storm cloud alpha.asset";var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(t!=null)return t;const int n=256;t=new Texture2D(n,n,TextureFormat.RGBA32,false){name="Soft non repeating cloud silhouette",wrapMode=TextureWrapMode.Clamp};for(int y=0;y<n;y++)for(int x=0;x<n;x++){float dx=(x-n*.5f)/(n*.5f),dy=(y-n*.5f)/(n*.5f);float edge=Mathf.Clamp01(1-Mathf.Sqrt(dx*dx+dy*dy));float noise=Mathf.PerlinNoise(x*.035f,y*.035f)*.6f+Mathf.PerlinNoise(x*.09f+3,y*.09f+7)*.4f;t.SetPixel(x,y,new Color(1,1,1,Mathf.Pow(edge,1.1f)*Mathf.SmoothStep(0,.7f,noise)));}t.Apply();AssetDatabase.CreateAsset(t,path);return t;}
 static Material Alpha(string n,Color tint){string path=Dir+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Legacy Shaders/Particles/Alpha Blended"));AssetDatabase.CreateAsset(m,path);}m.mainTexture=CloudTexture();m.SetColor("_TintColor",tint);return m;}
 static void MeshObject(string name,Transform parent,List<Vector3> v,List<int> triangles,Material material){string path="Assets/Prefabs/FinalRanking/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(m==null){m=new Mesh();AssetDatabase.CreateAsset(m,path);}m.Clear();m.SetVertices(v);m.SetUVs(0,v.Select(p=>new Vector2(p.x*.13f,Mathf.Atan2(p.y,p.z)/(Mathf.PI*2))).ToList());m.SetTriangles(triangles,0);m.RecalculateNormals();m.RecalculateBounds();EditorUtility.SetDirty(m);var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent,false);g.GetComponent<MeshFilter>().sharedMesh=m;g.GetComponent<MeshRenderer>().sharedMaterial=material;}
 static List<Vector3> Clip(List<Vector3> input,float x,bool keepAbove){var output=new List<Vector3>();if(input.Count==0)return output;Vector3 prev=input[input.Count-1];bool before=keepAbove?prev.x>=x:prev.x<=x;foreach(var p in input){bool inside=keepAbove?p.x>=x:p.x<=x;if(inside!=before){float t=(x-prev.x)/(p.x-prev.x);output.Add(Vector3.Lerp(prev,p,t));}if(inside)output.Add(p);prev=p;before=inside;}return output;}
 static void Slice(string name,Transform parent,Mesh source,float min,float max,Material material){var v=new List<Vector3>();var indices=new List<int>();var src=source.vertices;var tris=source.triangles;for(int i=0;i<tris.Length;i+=3){var polygon=Clip(Clip(new List<Vector3>{src[tris[i]],src[tris[i+1]],src[tris[i+2]]},min,true),max,false);if(polygon.Count<3)continue;int start=v.Count;foreach(var point in polygon){var p=point;if(Mathf.Abs(p.x-min)<.01f||Mathf.Abs(p.x-max)<.01f)p.x+=(Mathf.PerlinNoise(p.y*3+20,p.z*3+20)-.5f)*.6f;v.Add(p);}for(int j=1;j<polygon.Count-1;j++)indices.AddRange(new[]{start,start+j,start+j+1});int back=v.Count;for(int j=start;j<start+polygon.Count;j++)v.Add(v[j]);for(int j=1;j<polygon.Count-1;j++)indices.AddRange(new[]{back,back+j+1,back+j});}MeshObject(name,parent,v,indices,material);}
 public static void Build(){if(!EditorSceneManager.SaveOpenScenes())throw new Exception("Cannot save current scene");var setup=EditorSceneManager.GetSceneManagerSetup();EditorSceneManager.OpenScene("Assets/Scenes/FinalRanking.unity");var world=GameObject.Find("Ruined airport · editable fixed scenery").transform;
  Delete("Tail airline emblem");FractureAircraft(world);if(world.Find("Irregular impact fractures and debris")==null)Weather(world);Atmosphere(world);ScoreColumns();EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());
  EditorSceneManager.OpenScene("Assets/Scenes/Ranking.unity");var ui=Object.FindObjectOfType<RankingUI>();ui.scoreValues=new TMP_Text[ui.rankTexts.Length];for(int i=0;i<ui.rankTexts.Length;i++){var text=ui.rankTexts[i];var r=text.rectTransform;var existing=r.parent.Find("Right aligned score "+i);bool first=existing==null;Vector2 oldScorePosition=first?Vector2.zero:((RectTransform)existing).anchoredPosition;if(existing!=null)Object.DestroyImmediate(existing.gameObject);var copy=Object.Instantiate(text,r.parent);copy.name="Right aligned score "+i;copy.rectTransform.anchoredPosition=first?r.anchoredPosition+Vector2.right*(r.sizeDelta.x*.5f-85):oldScorePosition;copy.rectTransform.sizeDelta=new Vector2(140,r.sizeDelta.y);copy.alignment=TextAlignmentOptions.MidlineRight;copy.text="0점";ui.scoreValues[i]=copy;if(first){r.sizeDelta=new Vector2(r.sizeDelta.x-170,r.sizeDelta.y);r.anchoredPosition-=Vector2.right*85;}text.alignment=TextAlignmentOptions.MidlineLeft;}EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();EditorSceneManager.RestoreSceneManagerSetup(setup);
 }
 static void FractureAircraft(Transform world){var plane=GameObject.Find("PARTY AIR · detailed damaged passenger jet");if(plane==null)return;if(plane.transform.Find("Torn aft fuselage")!=null){var original=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Prefabs/FinalRanking/Contoured airliner fuselage.asset");var damaged=AssetDatabase.LoadAssetAtPath<Material>(Dir+"Soot streaked torn aircraft skin.mat");var rear=plane.transform.Find("Torn aft fuselage");var front=plane.transform.Find("Separated cockpit wreck");Object.DestroyImmediate(rear.Find("Jagged aft fuselage shell").gameObject);Object.DestroyImmediate(front.Find("Jagged forward fuselage shell").gameObject);Slice("Jagged aft fuselage shell",rear,original,-10,-2.1f,damaged);Slice("Jagged forward fuselage shell",front,original,.9f,9,damaged);return;}var p=plane.transform;var shell=p.Find("Contoured airliner fuselage");var source=shell.GetComponent<MeshFilter>().sharedMesh;var skin=Mat("Soot streaked torn aircraft skin",new Color(.44f,.47f,.46f));skin.mainTexture=NoiseTexture("Aircraft burn soot",new Color(.08f,.095f,.10f),new Color(.73f,.72f,.64f));skin.mainTextureScale=new Vector2(4,2);var dark=Mat("Scorched exposed aircraft interior",new Color(.07f,.08f,.09f));var metal=Mat("Bent exposed aluminium",new Color(.27f,.29f,.30f));
  var aft=Group("Torn aft fuselage",p,new Vector3(-1,-.8f,1));aft.localRotation=Quaternion.Euler(7,-9,-8);Slice("Jagged aft fuselage shell",aft,source,-10,-2.1f,skin);
  var fore=Group("Separated cockpit wreck",p,new Vector3(1.1f,-1.1f,-.35f));fore.localRotation=Quaternion.Euler(-4,11,9);Slice("Jagged forward fuselage shell",fore,source,.9f,9,skin);Object.DestroyImmediate(shell.gameObject);var belly=p.Find("Lower painted fuselage");if(belly!=null)Object.DestroyImmediate(belly.gameObject);
  foreach(Transform child in p.Cast<Transform>().ToArray()){if(child==aft||child==fore)continue;string n=child.name;if(n.StartsWith("Swept main wing")||n.StartsWith("Upturned winglet")||n.StartsWith("Wing flap joint")){child.localPosition+=new Vector3(-1,-1.65f,-.5f);child.localRotation*=Quaternion.Euler(12,7,-8);continue;}if(n.StartsWith("Turbofan engine")){child.localPosition+=new Vector3(1.5f,-.65f,-1);child.localRotation=Quaternion.Euler(-17,18,24);continue;}if(n=="Fuselage airline lettering"||n.StartsWith("Blast soot")||n.StartsWith("Exposed fuselage")||n.StartsWith("Engine pylon")){Object.DestroyImmediate(child.gameObject);continue;}float x=child.localPosition.x;if(x< -2.1f)child.SetParent(aft,false);else if(x>.9f)child.SetParent(fore,false);else if(n.Contains("Window")||n.Contains("window"))Object.DestroyImmediate(child.gameObject);}
  // Open ribs, floor beams and dangling cables make the blast opening read as a hollow wreck.
  for(int seam=0;seam<2;seam++){var parent=seam==0?aft:fore;float x=seam==0?-2.1f:.9f;for(int i=0;i<25;i++){float a=i*Mathf.PI*2/25,b=(i+1)*Mathf.PI*2/25;Beam("Exposed circular airframe rib",parent,new Vector3(x,Mathf.Sin(a)*1.25f,Mathf.Cos(a)*1.25f),new Vector3(x,Mathf.Sin(b)*1.25f,Mathf.Cos(b)*1.25f),.055f,metal);if(i%3==0){var edge=Box("Torn curled skin edge",parent,new Vector3(x+(i%2==0?.12f:-.12f),Mathf.Sin(a)*1.29f,Mathf.Cos(a)*1.29f),new Vector3(.42f,.10f,.21f),skin);edge.transform.localRotation=Quaternion.Euler(i*14,20,i*17);}}}
  for(int i=0;i<6;i++){float x=-2+i*.55f;Beam("Snapped cabin floor stringer",p,new Vector3(x,-.8f,-1),new Vector3(x+.3f,-1.5f,.7f),.075f,metal);Beam("Hanging power cable",p,new Vector3(x,.8f,.9f),new Vector3(x-.4f,-1.1f,.4f),.028f,dark);}
  for(int i=0;i<8;i++){var plate=Box("Scattered aircraft skin panel",world,new Vector3(-14+i*2.5f,.18f,8+i%3),new Vector3(1.8f,.07f,1.1f),skin);plate.transform.localRotation=Quaternion.Euler(i*4,25+i*31,i%2*17);}
  var fin=GameObject.Find("Swept vertical tail fin");if(fin!=null){fin.transform.localRotation*=Quaternion.Euler(0,0,15);}
 }
 static void Weather(Transform world){var ground=GameObject.Find("Airport apron · playable collision").GetComponent<Renderer>().sharedMaterial;ground.color=new Color(.55f,.58f,.59f);ground.mainTexture=NoiseTexture("Apron pitted aggregate",new Color(.12f,.14f,.15f),new Color(.42f,.43f,.40f),512,true);ground.mainTextureScale=new Vector2(24,24);ground.SetFloat("_Glossiness",.08f);
  foreach(var name in new[]{"Fractured light concrete","Charred terminal concrete","Weathered ivory"}){var m=AssetDatabase.LoadAssetAtPath<Material>(Dir+name+".mat");if(m!=null){m.mainTexture=NoiseTexture("Weathered concrete pores",new Color(.24f,.25f,.25f),new Color(.64f,.62f,.56f));m.mainTextureScale=new Vector2(3,3);m.SetFloat("_Glossiness",.08f);}}
  foreach(var t in world.GetComponentsInChildren<Transform>()){if(t.name.Contains("guidance")||t.name.Contains("Taxiway")||t.name.Contains("stop bar")){var r=t.GetComponent<Renderer>();if(r!=null)r.sharedMaterial.color=new Color(.48f,.42f,.22f);}if(t.name.Contains("cladding")||t.name.Contains("Cart")||t.name.Contains("Suitcase")||t.name.Contains("mullion")||t.name.Contains("Terminal vertical")){var filter=t.GetComponent<MeshFilter>();if(filter!=null)filter.sharedMesh=BeveledBox();}}
  var random=new System.Random(933);var scar=Mat("Deep apron fracture",new Color(.045f,.055f,.065f));var cracks=Group("Irregular impact fractures and debris",world,Vector3.zero);for(int c=0;c<26;c++){var v=new List<Vector3>();var triangles=new List<int>();Vector3 at=new Vector3(-22+(float)random.NextDouble()*44,.013f,-8+(float)random.NextDouble()*28);float angle=(float)random.NextDouble()*6.28f;for(int i=0;i<10;i++){Vector3 next=at+new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*(.3f+(float)random.NextDouble()*.7f);Vector3 side=Vector3.Cross(Vector3.up,next-at).normalized*(.008f+(float)random.NextDouble()*.025f);int start=v.Count;v.AddRange(new[]{at-side,at+side,next+side,next-side});triangles.AddRange(new[]{start,start+2,start+1,start,start+3,start+2});at=next;angle+=((float)random.NextDouble()-.5f)*1.1f;}MeshObject("Impact floor crack "+c,cracks,v,triangles,scar);}
  var scorch=Alpha("Soft blast soot stains",new Color(.035f,.04f,.045f,.65f));for(int i=0;i<8;i++){var patch=GameObject.CreatePrimitive(PrimitiveType.Quad);patch.name="Feathered blast scorch "+i;patch.transform.SetParent(world);patch.transform.localPosition=new Vector3(-17+i*4.5f,.018f,8+i%3*3);patch.transform.localRotation=Quaternion.Euler(90,0,i*41);patch.transform.localScale=new Vector3(4+i%3,3+i%2,1);Object.DestroyImmediate(patch.GetComponent<Collider>());patch.GetComponent<Renderer>().sharedMaterial=scorch;}
  // Remove glazing in an irregular blast zone, bend structural members and expose interior silhouettes.
  var glazing=world.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Curtain wall glazing")).ToArray();for(int i=0;i<glazing.Length;i++)if(i%4==1||i%9==0)Object.DestroyImmediate(glazing[i].gameObject);
  foreach(var t in world.GetComponentsInChildren<Transform>()){if(t.name.StartsWith("Exposed roof truss"))t.localRotation*=Quaternion.Euler(0,0,(t.GetSiblingIndex()%3-1)*12);}
  var concrete=Mat("Burnt terminal wall",new Color(.32f,.34f,.35f));concrete.mainTexture=NoiseTexture("Terminal damp streaks",new Color(.14f,.16f,.18f),new Color(.54f,.53f,.49f));for(int i=0;i<9;i++){var slab=Box("Broken terminal sill and parapet",world,new Vector3(-22+i*5.5f,1.2f,23.8f),new Vector3(3.8f,2.3f,.45f),concrete);slab.transform.localRotation=Quaternion.Euler(0,(i%3-1)*7,(i%2==0?-5:3));}
 }
 static void Atmosphere(Transform world){Delete("Ceremony storm atmosphere");var root=Group("Ceremony storm atmosphere",null,Vector3.zero);var effect=root.gameObject.AddComponent<AirportAtmosphere>();var material=Alpha("Rolling storm cloud layers",new Color(.16f,.19f,.24f,.75f));var clouds=new List<Transform>();var random=new System.Random(114);
  for(int i=0;i<14;i++){var cloud=GameObject.CreatePrimitive(PrimitiveType.Quad);cloud.name="Drifting storm cloud "+i;cloud.transform.SetParent(root);cloud.transform.localPosition=new Vector3(-48+i*7,12+(float)random.NextDouble()*8,39+(float)random.NextDouble()*12);cloud.transform.localRotation=Quaternion.Euler(0,0,(float)random.NextDouble()*12-6);cloud.transform.localScale=new Vector3(20+(float)random.NextDouble()*13,7+(float)random.NextDouble()*5,1);Object.DestroyImmediate(cloud.GetComponent<Collider>());cloud.GetComponent<Renderer>().sharedMaterial=material;cloud.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;clouds.Add(cloud.transform);}effect.clouds=clouds.ToArray();
  var dust=Group("Windblown apron dust",root,new Vector3(0,2,8));var ps=dust.gameObject.AddComponent<ParticleSystem>();var main=ps.main;main.loop=true;main.prewarm=true;main.startLifetime=new ParticleSystem.MinMaxCurve(9,15);main.startSpeed=.2f;main.startSize=new ParticleSystem.MinMaxCurve(.15f,.65f);main.startColor=new Color(.50f,.47f,.41f,.20f);main.maxParticles=160;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=ps.emission;emission.rateOverTime=9;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(42,4,30);var velocity=ps.velocityOverLifetime;velocity.enabled=true;velocity.space=ParticleSystemSimulationSpace.World;velocity.x=new ParticleSystem.MinMaxCurve(.6f,1.4f);velocity.y=new ParticleSystem.MinMaxCurve(-.03f,.07f);velocity.z=new ParticleSystem.MinMaxCurve(-.12f,.12f);ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=Alpha("Fine airborne ash",new Color(.65f,.60f,.52f,.22f));var over=ps.colorOverLifetime;over.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.7f,.2f),new GradientAlphaKey(.5f,.7f),new GradientAlphaKey(0,1)});over.color=gradient;
  RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.24f,.28f,.35f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.20f,.25f,.31f);RenderSettings.fogDensity=.012f;Camera.main.backgroundColor=RenderSettings.fogColor;var sun=GameObject.Find("Late afternoon through smoke").GetComponent<Light>();sun.color=new Color(.66f,.76f,.92f);sun.intensity=.75f;
  var fill=Group("Soft survivor key light",root,new Vector3(-4,7,-6)).gameObject.AddComponent<Light>();fill.type=LightType.Spot;fill.color=new Color(1,.83f,.59f);fill.intensity=4;fill.range=28;fill.spotAngle=70;fill.transform.LookAt(new Vector3(0,1,3));fill.shadows=LightShadows.Soft;effect.embers=world.GetComponentsInChildren<Light>();
 }
 static TMP_Text Value(TMP_Text row,string name,Vector2 position,Vector2 size){var existing=row.transform.parent.Find(name);if(existing!=null)Object.DestroyImmediate(existing.gameObject);var value=Object.Instantiate(row,row.transform.parent);value.name=name;value.rectTransform.anchoredPosition=position;value.rectTransform.sizeDelta=size;value.alignment=TextAlignmentOptions.MidlineRight;value.text="0점";value.enableAutoSizing=true;value.fontSizeMin=22;value.fontSizeMax=44;return value;}
 static void ScoreColumns(){var final=Object.FindObjectOfType<FinalRanking>();final.scoreValues=new TMP_Text[4];for(int i=0;i<4;i++){var row=final.scoreRows[i];float y=15-i*100;row.rectTransform.anchoredPosition=new Vector2(615,y);row.rectTransform.sizeDelta=new Vector2(320,95);row.alignment=TextAlignmentOptions.MidlineLeft;final.scoreValues[i]=Value(row,"Right aligned final score "+i,new Vector2(840,y),new Vector2(100,95));}}
}
#endif
